// Append the longer levels + grand finales (generated by gen_long.js, picked in gen/pick.json) to chapters 2-6 (idempotent).
// Each chapter keeps its original levels first; the last appended level is the chapter's grand finale (3 lives).
const fs = require('fs'), path = require('path');
const P = path.join(__dirname, 'chapters.json'), CH = JSON.parse(fs.readFileSync(P, 'utf8'));
const PICK = JSON.parse(fs.readFileSync(path.join(__dirname, 'gen', 'pick.json'), 'utf8'));
const BASE = { abyss: 6, winds: 5, rocks: 5, rainbow: 5, ice: 5 };
const META = {
  abyss: [['c2a', 'Deep Descent', 'Three dark chambers stacked high. Let ramps and mirrors carry you upward.'],
          ['c2b', 'Lightless Corridor', 'A long dark hall. Mirrors turn you, the black hole bends your path, launch pads kick you off the edge.'],
          ['c2f', 'Heart of the Abyss', 'Grand finale - only 3 lives! Stars burn and black holes swallow. Climb all four chambers.']],
  winds: [['c3a', 'Updraft Tower', 'Climb the tower: let the quarter-pipes fling you up and around the walls.'],
          ['c3b', 'Jet Stream', 'A long run east. Pipes boost you, winds push you, wells slow time.'],
          ['c3f', 'Solar Summit', 'Grand finale - only 3 lives! Pipes, winds, wells and crushing platforms all the way up.']],
  rocks: [['c4a', 'Meteor Shaft', 'A tall shaft of drifting rocks and hail. Watch the rhythm before every leap.'],
          ['c4b', 'Rock Garden', 'A long run east through a field of drifting rocks. Time each leap between them.'],
          ['c4f', 'Asteroid Gauntlet', 'Grand finale - only 3 lives! Rocks, rings and hail in every chamber.']],
  rainbow: [['c5a', 'Colour Cascade', 'Three sky gardens, each locked by coloured glass. Find the right prism, then ride the rainbows up.'],
            ['c5b', 'Thunder Meadow', 'A friendly storm! A lightning lane darkens and sparkles before a bolt. Cross while the sky is calm.'],
            ['c5f', "Rainbow's End", 'Grand finale - only 3 lives! Prisms, gates, rain clouds and lightning on the way to the end of the rainbow.']],
  ice: [['c6a', 'Glacier Climb', 'Light the lantern to melt the ice, then catch the sunlight and smash through the glacier.'],
        ['c6b', 'Icicle Hollow', 'Icicles shiver before they fall. Let them drop, then dash under. Shrink to slip through the crack.'],
        ['c6f', 'Heart of Winter', 'Grand finale - only 3 lives! Lanterns, glaciers, cracks and falling icicles all the way up.']],
};
for (const ch of CH) {
  const meta = META[ch.id]; if (!meta) continue;
  ch.levels = ch.levels.slice(0, BASE[ch.id]);
  meta.forEach(([key, name, hint], k) => {
    const def = JSON.parse(fs.readFileSync(path.join(__dirname, PICK[key]), 'utf8'));
    def.name = name; def.hint = hint; def.long = true; if (!ch.scroll) def.scroll = true;
    if (k === meta.length - 1) def.finale = true;
    ch.levels.push(def);
  });
}
fs.writeFileSync(P, JSON.stringify(CH, null, 1));
console.log('chapters:', CH.map((c) => c.name + ' (' + c.levels.length + ')').join(', '));
